from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    """
    rules:  rewrite rule dictionaries in priority order
    urls:   list of URL strings

    Returns a list containing rewritten URLs or None for blocked URLs.
    """

    def host_matches(host, match_value):
        if host is None:
            return False

        host = host.lower()
        match_value = match_value.lower()

        if match_value.startswith("*."):
            base_domain = match_value[2:]
            # The base domain itself does not match.
            return host != base_domain and host.endswith("." + base_domain)

        return host == match_value

    def replace_host(parts, new_host):
        """
        Replace only the hostname while preserving user information and port.
        """
        netloc = parts.netloc

        userinfo = ""
        hostport = netloc

        if "@" in netloc:
            userinfo, hostport = netloc.rsplit("@", 1)
            userinfo += "@"

        port_suffix = ""

        if hostport.startswith("["):
            # IPv6 address such as [::1]:8080
            closing_bracket = hostport.find("]")
            if closing_bracket != -1:
                port_suffix = hostport[closing_bracket + 1:]
        elif hostport.count(":") == 1:
            # Ordinary hostname with an optional port
            _, possible_port = hostport.rsplit(":", 1)
            if possible_port.isdigit():
                port_suffix = ":" + possible_port

        # Bracket an IPv6 replacement host if necessary.
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        new_netloc = userinfo + new_host + port_suffix
        return parts._replace(netloc=new_netloc)

    results = []

    for original_url in urls:
        parts = urlsplit(original_url)
        rewritten_url = original_url
        matched = False

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            is_match = False

            if match_type == "path_prefix":
                is_match = parts.path.startswith(match_value)

            elif match_type == "host":
                is_match = host_matches(parts.hostname, match_value)

            elif match_type == "query_param":
                query_params = parse_qsl(
                    parts.query,
                    keep_blank_values=True
                )
                is_match = any(
                    name == match_value
                    for name, _ in query_params
                )

            if not is_match:
                continue

            matched = True

            if action == "block":
                rewritten_url = None
                break

            action_value = rule["action_value"]

            if action == "strip_prefix":
                new_path = parts.path

                if new_path.startswith(action_value):
                    new_path = new_path[len(action_value):]

                if not new_path:
                    new_path = "/"

                rewritten_url = urlunsplit(
                    parts._replace(path=new_path)
                )

            elif action == "redirect_host":
                rewritten_url = urlunsplit(
                    replace_host(parts, action_value)
                )

            elif action == "add_query_param":
                new_query = parts.query
                if new_query:
                    new_query += "&" + action_value
                else:
                    new_query = action_value

                rewritten_url = urlunsplit(
                    parts._replace(query=new_query)
                )

            break  # Only the first matching rule is applied.

        results.append(rewritten_url)

    return results
